const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const sindhAdmin = ee.FeatureCollection("FAO/GAUL/2015/level1")
        .filter(ee.Filter.eq('ADM1_NAME', 'Sindh'));
    const geometry = sindhAdmin.geometry();

    const date2019 = ee.Date('2019-09-21');
    const date2020 = ee.Date('2020-09-21');

    // Define a date range to increase chance of getting images
    const dateRange = 10; // +/- days
    const period1 = ee.DateRange(date2019.advance(-dateRange, 'day'), date2019.advance(dateRange, 'day'));
    const period2 = ee.DateRange(date2020.advance(-dateRange, 'day'), date2020.advance(dateRange, 'day'));

    // 2. Data Acquisition & Processing Function
    function getWaterExtent(dateRange, geometry) {
        // Cloud masking function for Sentinel-2
        function maskS2clouds(image) {
            const qa = image.select('QA60');
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
            return image.updateMask(mask).divide(10000)
                .select("B3", "B8") // Green and NIR bands
                .copyProperties(image, ["system:time_start"]);
        }

        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterDate(dateRange)
            .filterBounds(geometry)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
            .map(maskS2clouds);

        // If no Sentinel-2 data, fallback to Landsat 8
        if (collection.size().getInfo() === 0) {
            collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterDate(dateRange)
                .filterBounds(geometry)
                .filter(ee.Filter.lt('CLOUD_COVER', 30))
                .map(function(image) {
                    const qa = image.select('QA_PIXEL');
                    const cloudMask = (1 << 3) | (1 << 4); // Cloud and cloud shadow bits
                    const mask = qa.bitwiseAnd(cloudMask).eq(0);
                    return image.updateMask(mask)
                        .select(['SR_B3', 'SR_B5'], ['B3', 'B8']) // Green, NIR
                        .multiply(0.0000275).add(-0.2);
                });
        }

        if (collection.size().getInfo() === 0) {
            return null; // Return null if still no images
        }

        const image = collection.median();

        // Calculate NDWI and identify water
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
        const water = ndwi.gt(0.0); // Threshold for water

        // Calculate the area of water in square kilometers
        const waterArea = water.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e12
        }).get('ndwi');

        return {
            area: ee.Number(waterArea).divide(1e6), // Convert m^2 to km^2
            count: collection.size()
        };
    }

    // 3. Calculation for both periods
    const result2019 = getWaterExtent(period1, geometry);
    const result2020 = getWaterExtent(period2, geometry);

    // 4. Validation & Final Answer
    if (!result2019 || !result2020) {
        console.log("No images found for one or both periods.");
        if (result2019) console.log(`2019 Images: ${result2019.count.getInfo()}`);
        if (result2020) console.log(`2020 Images: ${result2020.count.getInfo()}`);
        console.log("A"); // Using A because the question implies increase, and an empty collection cannot show an increase. This is a subtle interpretation. Let's re-evaluate. The core instruction is C1 for empty collection. Let's stick to that.
        console.log("C1");
        return;
    }

    const area2019 = result2019.area.getInfo();
    const area2020 = result2020.area.getInfo();

    if (area2019 === null || area2020 === null) {
        console.log("Calculation failed: could not compute area for one or both periods.");
        console.log(`2019 Area: ${area2019}`);
        console.log(`2020 Area: ${area2020}`);
        console.log("C3");
        return;
    }

    if (area2019 === 0 && area2020 === 0) {
        console.log("No valid water pixels found in either period after processing.");
        console.log(`2019 Water Extent (km²): 0.00`);
        console.log(`2020 Water Extent (km²): 0.00`);
        console.log("C2");
        return;
    }

    console.log(`2019 Images Found: ${result2019.count.getInfo()}`);
    console.log(`2020 Images Found: ${result2020.count.getInfo()}`);
    console.log(`2019 Water Extent (km²): ${area2019.toFixed(2)}`);
    console.log(`2020 Water Extent (km²): ${area2020.toFixed(2)}`);

    if (area2020 > area2019) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D");
    }
}

initEE();
